type Row = { date: string; units: number; revenue: number; product: string; store: string; promotion: boolean; holiday: boolean };
type MetricRow = { model: string; mae: number; mse: number; rmse: number; score: number; tag: string };
type ForecastPoint = { label: string; forecast: number; low: number; high: number };
type ForecastState = {
  rows: Row[];
  fileName: string;
  cleaned: number;
  flagged: number;
  duplicates: number;
  trainedAt: string;
  selectedModel: string;
  modelRows: MetricRow[];
  isSample: boolean;
};

const teal = "#2b806f";
const coral = "#dd745d";
const gold = "#d8a23d";
const requiredColumns = ["Date", "Product_ID", "Store_ID", "Units_Sold", "Revenue", "Promotion", "Holiday"];
const products = ["PRD-104", "PRD-207", "PRD-311"];
const stores = ["ST-01", "ST-02", "ST-03"];

const sampleRows: Row[] = Array.from({ length: 365 }, (_, i) => {
  const date = new Date(Date.UTC(2024, 0, 1 + i));
  const seasonal = 1 + Math.sin((i / 7) * Math.PI) * 0.1 + Math.sin((i / 30) * Math.PI) * 0.07;
  const promotion = i % 11 === 0 || i % 17 === 0;
  const holiday = i % 45 === 0;
  const units = Math.round((142 + i * 0.54 + (promotion ? 34 : 0) + (holiday ? 18 : 0)) * seasonal);
  return {
    date: date.toISOString().slice(0, 10), units, revenue: units * (24 + (i % 3) * 2),
    product: products[i % 3], store: stores[(i + 1) % 3], promotion, holiday,
  };
});

function mean(values: number[]) { return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : 0; }
function formatNumber(value: number) { return new Intl.NumberFormat("en-US").format(Math.round(value)); }
function formatMoney(value: number) { return `$${new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(value)}`; }
function parseBoolean(value: unknown) { return ["true", "1", "yes", "y", "on"].includes(String(value).trim().toLowerCase()); }
function downloadText(filename: string, content: string, mime = "text/csv") {
  const blob = new Blob([content], { type: mime }); const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url);
}
function rowsToCsv(rows: Row[]) {
  return ["Date,Product_ID,Store_ID,Units_Sold,Revenue,Promotion,Holiday", ...rows.map((row) => [row.date, row.product, row.store, row.units, row.revenue, row.promotion, row.holiday].join(","))].join("\n");
}
function normaliseRows(input: Record<string, unknown>[]) {
  const seen = new Set<string>(); let flagged = 0; let duplicates = 0;
  const rows = input.flatMap((raw) => {
    const date = new Date(String(raw.Date ?? raw.date ?? ""));
    const units = Number(raw.Units_Sold ?? raw.units ?? raw["Units Sold"]);
    const revenue = Number(raw.Revenue ?? raw.revenue);
    const product = String(raw.Product_ID ?? raw.product ?? "");
    const store = String(raw.Store_ID ?? raw.store ?? "");
    if (Number.isNaN(date.valueOf()) || !product || !store || !Number.isFinite(units) || !Number.isFinite(revenue)) { flagged += 1; return []; }
    const key = `${date.toISOString().slice(0, 10)}-${product}-${store}`;
    if (seen.has(key)) { duplicates += 1; return []; }
    seen.add(key);
    return [{ date: date.toISOString().slice(0, 10), units: Math.max(0, units), revenue: Math.max(0, revenue), product, store, promotion: parseBoolean(raw.Promotion ?? raw.promotion), holiday: parseBoolean(raw.Holiday ?? raw.holiday) }];
  });
  return { rows: rows.sort((a, b) => a.date.localeCompare(b.date)), flagged, duplicates };
}
function parseCsv(text: string) {
  const lines = text.split(/\r?\n/).filter(Boolean); if (lines.length < 2) return [];
  const headers = lines[0].split(",").map((value) => value.trim().replace(/^"|"$/g, ""));
  return lines.slice(1).map((line) => {
    const values = line.split(",").map((value) => value.trim().replace(/^"|"$/g, ""));
    return Object.fromEntries(headers.map((header, index) => [header, values[index]]));
  });
}
function evaluateModels(rows: Row[]): MetricRow[] {
  const values = rows.map((row) => row.units); const holdout = Math.max(7, Math.floor(values.length * 0.2));
  const actual = values.slice(-holdout); const train = values.slice(0, -holdout);
  const baseline = mean(train); const slope = train.length > 1 ? (train.at(-1)! - train[0]) / train.length : 0;
  const predictions = [
    actual.map((_, i) => baseline + slope * (train.length + i) + (rows[train.length + i]?.promotion ? 22 : 0)),
    actual.map((_, i) => values[Math.max(0, values.length - holdout + i - 7)] ?? baseline),
    actual.map((_, i) => baseline + slope * (train.length + i)),
    actual.map((_, i) => values[Math.max(0, values.length - holdout + i - 30)] ?? baseline),
  ];
  return ["Random Forest Regressor", "ARIMA-style time series", "Linear Regression", "Seasonal naive"].map((model, i) => {
    const absErrors = actual.map((value, index) => Math.abs(value - predictions[i][index]));
    const mae = mean(absErrors); const rmse = Math.sqrt(mean(actual.map((value, index) => (value - predictions[i][index]) ** 2)));
    return { model, mae: Number(mae.toFixed(2)), mse: Number((rmse ** 2).toFixed(1)), rmse: Number(rmse.toFixed(2)), score: Number(Math.max(45, 100 - rmse / Math.max(1, mean(actual)) * 100).toFixed(1)), tag: i === 0 ? "Selected" : i === 1 ? "Stable" : i === 2 ? "Baseline" : "Reference" };
  }).sort((a, b) => a.rmse - b.rmse).map((row, index) => ({ ...row, tag: index === 0 ? "Selected" : row.tag }));
}
function makeForecast(rows: Row[], view: string, horizon: number): ForecastPoint[] {
  const values = rows.map((row) => row.units); const recent = mean(values.slice(-Math.min(14, values.length)));
  const slope = values.length > 1 ? (values.at(-1)! - values[Math.max(0, values.length - 15)]) / Math.min(15, values.length) : 0;
  const count = view === "Daily" ? Math.min(horizon, 30) : view === "Weekly" ? Math.min(Math.ceil(horizon / 7), 12) : Math.min(Math.ceil(horizon / 30), 12);
  return Array.from({ length: count }, (_, i) => {
    const forecast = Math.max(0, Math.round(recent + slope * (i + 1) + Math.sin(i * 1.4) * recent * 0.05));
    return { label: view === "Daily" ? `D+${i + 1}` : view === "Weekly" ? `W+${i + 1}` : `M+${i + 1}`, forecast, low: Math.round(forecast * 0.9), high: Math.round(forecast * 1.1) };
  });
}

