function Kpi({ label, value, change, note, icon: I, negative = false }: { label: string; value: string; change: string; note: string; icon: typeof Activity; negative?: boolean }) { return <Card className="rise-2 relative overflow-hidden p-4"><div className="absolute right-0 top-0 h-16 w-16 rounded-bl-[50px] bg-[hsl(var(--muted))]" /><div className="relative flex items-start justify-between"><div><div className="mb-2 text-[11px] font-medium text-[hsl(var(--muted-foreground))]">{label}</div><div className="mono text-[24px] font-bold tracking-[-.06em]">{value}</div><div className={cx("mt-2 flex items-center gap-1 text-[11px] font-bold", negative ? "text-[#bd6451]" : "text-[#3c8d6e]")}>{negative ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />}{change}<span className="font-normal text-[hsl(var(--muted-foreground))]">{note}</span></div></div><div className="relative rounded-lg bg-[hsl(var(--muted))] p-2 text-[hsl(var(--primary))]"><I size={16} /></div></div></Card>; }
