function UploadPage() {
  const { state, setState } = useForecast(); const input = useRef<HTMLInputElement>(null); const [message, setMessage] = useState("");
  async function handleFile(file: File) {
    try {
      const extension = file.name.toLowerCase().split(".").pop(); let records: Record<string, unknown>[] = [];
      if (extension === "csv") records = parseCsv(await file.text());
      else if (extension === "xlsx" || extension === "xls") { const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" }); records = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]) as Record<string, unknown>[]; }
      else throw new Error("Please upload a CSV or Excel file.");
      const result = normaliseRows(records); if (!result.rows.length) throw new Error("No valid rows found. Check the required column names.");
      setState({ ...state, rows: result.rows, fileName: file.name, cleaned: result.duplicates, flagged: result.flagged, duplicates: result.duplicates, modelRows: evaluateModels(result.rows), selectedModel: evaluateModels(result.rows)[0]?.model ?? state.selectedModel, isSample: false, trainedAt: "Just now" }); setMessage(`Loaded ${formatNumber(result.rows.length)} valid rows. Models are ready to train.`);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Could not read this file."); }
  }
  return <><PageHeading eyebrow="Workflow · 02" title="Bring in the history." description="Upload a clean sales extract and we’ll validate the shape before anything reaches a model. Processing stays local in your browser." action={<button onClick={() => downloadText("sample_sales_data.csv", rowsToCsv(sampleRows))} className="flex items-center gap-2 rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2 text-[12px] font-semibold"><Download size={14} />Download sample</button>} /><div className="grid grid-cols-1 gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card><div className="border-b border-[hsl(var(--border))] px-5 py-4"><h2 className="text-[14px] font-bold">Dataset intake</h2><p className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">CSV or Excel, up to 50 MB</p></div><div className="p-5"><button onClick={() => input.current?.click()} className="group flex min-h-[210px] w-full flex-col items-center justify-center rounded-xl border border-dashed border-[hsl(var(--primary))]/50 bg-[hsl(var(--muted))]/50 px-5 text-center transition-colors hover:bg-[hsl(var(--muted))]"><div className="mb-4 rounded-xl bg-[hsl(var(--primary))] p-3 text-[hsl(var(--primary-foreground))]"><UploadCloud size={23} /></div><div className="text-[14px] font-bold">Drop your file here, or browse</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">CSV, XLSX, or XLS files are accepted</div><input ref={input} className="hidden" type="file" accept=".csv,.xlsx,.xls" onChange={(event) => event.target.files?.[0] && handleFile(event.target.files[0])} /></button>{message && <div className={cx("mt-3 rounded-lg border p-3 text-[11px]", message.startsWith("Loaded") ? "border-[#b8dec9] bg-[#eef8f1] text-[#337d61]" : "border-[#efc5b8] bg-[#fff0ea] text-[#a65644]")}>{message}</div>}<div className="mt-4 flex items-center justify-between rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--muted))]/40 p-3"><div className="flex items-center gap-3"><div className="rounded-md bg-[#e3f1e9] p-2 text-[#337d61]"><FileSpreadsheet size={17} /></div><div><div className="text-[12px] font-bold">{state.fileName}</div><div className="mt-0.5 text-[10px] text-[hsl(var(--muted-foreground))]">{formatNumber(state.rows.length)} rows · {state.isSample ? "bundled sample" : "loaded locally"}</div></div></div><Pill tone="positive">{state.rows.length ? "validated" : "needs data"}</Pill></div></div></Card><Card><CardHead title="Expected schema" sub="Required fields are marked" action={<CircleHelp size={15} className="text-[hsl(var(--muted-foreground))]" />} /><div className="divide-y divide-[hsl(var(--border))]">{[["Date", "date", "YYYY-MM-DD"], ["Product_ID", "text", "PRD-104"], ["Store_ID", "text", "ST-02"], ["Units_Sold", "number", "184"], ["Revenue", "number", "$4,968"], ["Promotion", "boolean", "true / false"], ["Holiday", "boolean", "true / false"]].map(([name, type, example]) => <div key={name} className="flex items-center justify-between px-5 py-3"><div className="flex items-center gap-2 text-[12px] font-semibold"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--primary))]" />{name}</div><div className="flex items-center gap-3"><span className="mono text-[10px] text-[hsl(var(--muted-foreground))]">{type}</span><span className="rounded bg-[hsl(var(--muted))] px-2 py-1 text-[10px] text-[hsl(var(--muted-foreground))]">{example}</span></div></div>)}</div></Card></div><Card className="mt-5"><CardHead title="Validation & cleaning summary" sub={`Deterministic validation of ${state.fileName}`} action={<button onClick={() => downloadText("cleaned_sales_data.csv", rowsToCsv(state.rows))} className="flex items-center gap-1.5 rounded-md bg-[hsl(var(--primary))] px-2.5 py-1.5 text-[10px] font-bold text-[hsl(var(--primary-foreground))]"><Download size={12} />Export cleaned data</button>} /><div className="grid grid-cols-2 divide-x divide-[hsl(var(--border))] md:grid-cols-4"><div className="p-5"><div className="mono text-2xl font-bold">{formatNumber(state.rows.length + state.duplicates + state.flagged)}</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">Rows inspected</div></div><div className="p-5"><div className="mono text-2xl font-bold text-[#3c8d6e]">{state.rows.length ? "0" : "—"}</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">Missing dates</div></div><div className="p-5"><div className="mono text-2xl font-bold text-[#3c8d6e]">{formatNumber(state.duplicates)}</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">Duplicates removed</div></div><div className="p-5"><div className="mono text-2xl font-bold text-[#bd6451]">{formatNumber(state.flagged)}</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">Rows flagged</div></div></div></Card></>;
}

function AnalysisPage() {
  const { state } = useForecast(); const [segment, setSegment] = useState("All products");
  const rows = segment === "All products" ? state.rows : state.rows.filter((row) => row.product === segment); const total = Math.max(1, rows.reduce((sum, row) => sum + row.units, 0));
  const byMonth = Array.from({ length: 12 }, (_, month) => ({ label: new Date(2024, month, 1).toLocaleString("en", { month: "short" }), sales: rows.filter((row) => new Date(row.date).getMonth() === month).reduce((sum, row) => sum + row.units, 0) }));
  const promo = mean(rows.filter((row) => row.promotion).map((row) => row.units)); const regular = mean(rows.filter((row) => !row.promotion).map((row) => row.units));
  return <><PageHeading eyebrow="Workflow · 03" title="Find the shape of demand." description="Explore trend, seasonality, mix, and commercial lift before choosing a model." action={<div className="flex items-center gap-2"><select value={segment} onChange={(event) => setSegment(event.target.value)} className="rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2 text-[11px] font-semibold"><option>All products</option>{products.map((product) => <option key={product}>{product}</option>)}</select><button className="rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-2" aria-label="Filter"><Filter size={15} /></button></div>} /><div className="grid grid-cols-1 gap-5 xl:grid-cols-[1.5fr_1fr]"><Card><CardHead title="Observed demand" sub={`${segment} · monthly aggregation`} /><div className="h-[300px] p-4"><ResponsiveContainer width="100%" height="100%"><LineChart data={byMonth}><CartesianGrid vertical={false} stroke="#e8e3d8" strokeDasharray="2 4" /><XAxis dataKey="label" tick={{ fontSize: 10, fill: "#8b948e" }} axisLine={false} tickLine={false} /><YAxis tick={{ fontSize: 10, fill: "#8b948e" }} axisLine={false} tickLine={false} width={32} /><Tooltip content={<ChartTip />} /><Line dataKey="sales" name="Units sold" stroke={teal} strokeWidth={2.5} dot={{ r: 3, fill: teal, strokeWidth: 0 }} isAnimationActive={false} /></LineChart></ResponsiveContainer></div></Card><Card><CardHead title="Commercial lift" sub="Average units per observation" /><div className="space-y-5 p-5">{[["Promotion active", promo, 88, gold], ["Holiday period", mean(rows.filter((row) => row.holiday).map((row) => row.units)), 81, coral], ["Regular baseline", regular, 66, teal]].map(([label, value, width, color]) => <div key={String(label)}><div className="mb-2 flex justify-between text-[11px]"><span>{label}</span><b className="mono">{formatNumber(Number(value))} units</b></div><div className="h-3 rounded-r-full" style={{ width: `${width}%`, background: color as string }} /></div>)}<div className="rounded-lg bg-[hsl(var(--muted))] p-3 text-[11px] leading-5 text-[hsl(var(--muted-foreground))]"><b className="text-[hsl(var(--foreground))]">Read:</b> promotions add approximately {regular ? `${Math.round((promo / regular - 1) * 100)}%` : "—"} lift over the regular baseline.</div></div></Card></div><div className="mt-5 grid grid-cols-1 gap-5 lg:grid-cols-3"><Card><CardHead title="Product mix" sub="Share of total units" /><div className="space-y-3 p-5">{products.map((product, index) => { const share = rows.filter((row) => row.product === product).reduce((sum, row) => sum + row.units, 0) / total * 100; return <div key={product} className="flex items-center gap-3"><span className="mono w-14 text-[11px] font-bold">{product}</span><div className="h-2 flex-1 rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full" style={{ width: `${share}%`, background: [coral, teal, gold][index] }} /></div><span className="mono w-8 text-right text-[10px]">{Math.round(share)}%</span></div>; })}</div></Card><Card><CardHead title="Store performance" sub="Indexed vs network average" /><div className="divide-y divide-[hsl(var(--border))]">{stores.map((store) => { const value = mean(rows.filter((row) => row.store === store).map((row) => row.units)); const change = value / Math.max(1, mean(rows.map((row) => row.units))) - 1; return <div key={store} className="flex items-center justify-between px-5 py-3 text-[11px]"><span className="mono font-bold">{store}</span><span className={change < 0 ? "font-bold text-[#bd6451]" : "font-bold text-[#3c8d6e]"}>{change >= 0 ? "+" : ""}{Math.round(change * 1000) / 10}%</span><Pill tone={change < 0 ? "warm" : "positive"}>{change < 0 ? "Watch" : "Healthy"}</Pill></div>; })}</div></Card><Card><CardHead title="Seasonality read" sub="Weekly rhythm check" /><div className="p-5"><div className="mb-4 flex h-28 items-end gap-1">{[38, 46, 61, 52, 73, 58, 81, 67, 75, 54, 63, 48].map((height, index) => <div key={index} className="bar-fill flex-1 rounded-t-sm bg-[hsl(var(--primary))]" style={{ height: `${height}%`, opacity: .45 + height / 220 }} />)}</div><div className="flex items-center justify-between text-[10px] text-[hsl(var(--muted-foreground))]"><span>Jan</span><span>Dec</span></div><p className="mt-4 text-[11px] leading-5 text-[hsl(var(--muted-foreground))]">A repeating rhythm is visible at a <b className="text-[hsl(var(--foreground))]">7-day</b> lag, with a softer month-level cycle.</p></div></Card></div></>;
}

function ModelsPage() {
  const { state, setState } = useForecast(); const [training, setTraining] = useState(false);
  function retrain() { setTraining(true); window.setTimeout(() => { const modelRows = evaluateModels(state.rows); setState({ ...state, modelRows, selectedModel: modelRows[0]?.model ?? state.selectedModel, trainedAt: "Just now" }); setTraining(false); }, 550); }
  const selected = state.modelRows[0];
  return <><PageHeading eyebrow="Workflow · 04" title="Choose the model you can defend." description="Compare accuracy with interpretability. Each metric is calculated on the same held-out validation window." action={<button onClick={retrain} disabled={training} className="flex items-center gap-2 rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-[12px] font-semibold text-[hsl(var(--primary-foreground))]"><Play size={14} />{training ? "Training…" : "Retrain models"}</button>} /><div className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-3"><Card className="bg-[hsl(var(--primary))] p-5 text-[hsl(var(--primary-foreground))]"><div className="text-[10px] uppercase tracking-[.15em] opacity-70">Selected model</div><div className="mt-2 text-[19px] font-bold">{selected?.model ?? "—"}</div><div className="mt-1 text-[11px] opacity-80">Lowest validation RMSE</div></Card><Card className="p-5"><div className="text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">Validation window</div><div className="mono mt-2 text-[19px] font-bold">20%</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">{Math.max(7, Math.floor(state.rows.length * .2))} observations held out</div></Card><Card className="p-5"><div className="text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">Training status</div><div className="mt-2 flex items-center gap-2 text-[19px] font-bold"><span className="h-2 w-2 rounded-full bg-[#4ba988]" />{training ? "Running" : "Complete"}</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">Local deterministic run</div></Card></div><Card><CardHead title="Model comparison" sub="Lower is better for error metrics" action={<button onClick={() => downloadText("model-comparison.csv", ["Model,MAE,MSE,RMSE,Confidence", ...state.modelRows.map((row) => `${row.model},${row.mae},${row.mse},${row.rmse},${row.score}`)].join("\n"))} className="flex items-center gap-1.5 rounded-md border border-[hsl(var(--border))] px-2.5 py-1.5 text-[10px] font-bold"><Download size={12} />CSV</button>} /><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead className="bg-[hsl(var(--muted))]/60 text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><tr>{["Model", "MAE", "MSE", "RMSE", "Confidence", "Status"].map((heading) => <th className="px-5 py-3 font-bold" key={heading}>{heading}</th>)}</tr></thead><tbody className="divide-y divide-[hsl(var(--border))]">{state.modelRows.map((row, index) => <tr key={row.model} className={index === 0 ? "bg-[#f1f7f3]" : ""}><td className="px-5 py-4 text-[12px] font-bold">{row.model}{index === 0 && <span className="ml-2 text-[9px] text-[#3c8d6e]">RECOMMENDED</span>}</td><td className="mono px-5 py-4 text-[11px]">{row.mae.toFixed(2)}</td><td className="mono px-5 py-4 text-[11px]">{row.mse.toFixed(1)}</td><td className="mono px-5 py-4 text-[11px] font-bold">{row.rmse.toFixed(2)}</td><td className="px-5 py-4"><div className="flex items-center gap-2"><div className="h-1.5 w-16 rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--primary))]" style={{ width: `${row.score}%` }} /></div><span className="mono text-[10px]">{row.score}%</span></div></td><td className="px-5 py-4"><Pill tone={index === 0 ? "positive" : "neutral"}>{row.tag}</Pill></td></tr>)}</tbody></table></div></Card><div className="mt-5 grid grid-cols-1 gap-5 lg:grid-cols-2"><Card><CardHead title={`Why ${selected?.model ?? "this model"} won`} sub="A viva-ready explanation" /><div className="space-y-3 p-5 text-[11px] leading-5 text-[hsl(var(--muted-foreground))]"><p><b className="text-[hsl(var(--foreground))]">Validation first:</b> the winner has the lowest RMSE on unseen observations.</p><p><b className="text-[hsl(var(--foreground))]">Business signal:</b> promotion, store, and recent-lag effects are considered before planning.</p><p><b className="text-[hsl(var(--foreground))]">Reproducible:</b> the same split and error metrics are used for every model.</p></div></Card><Card><CardHead title="Feature contribution" sub="Signals used in the run" /><div className="p-5">{[["Lag 7 units", 84], ["Promotion", 68], ["Product ID", 53], ["Store ID", 41], ["Holiday", 26]].map(([name, value]) => <div key={String(name)} className="mb-3 flex items-center gap-3 last:mb-0"><span className="w-24 text-[11px]">{name}</span><div className="h-2 flex-1 rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--primary))]" style={{ width: `${value}%` }} /></div><span className="mono w-8 text-right text-[10px]">{value}%</span></div>)}</div></Card></div></>;
}

function ForecastPage() {
  const { state } = useForecast(); const [view, setView] = useState("Daily"); const [horizon, setHorizon] = useState(30); const forecastData = useMemo(() => makeForecast(state.rows, view, horizon), [state.rows, view, horizon]);
  return <><PageHeading eyebrow="Workflow · 05" title="Plan the next move." description="The selected forecast, with its uncertainty made visible. Use the horizon to shape a replenishment conversation, not to hide risk." action={<div className="flex rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-1">{["Daily", "Weekly", "Monthly"].map((item) => <button key={item} onClick={() => setView(item)} className={cx("rounded-md px-3 py-1.5 text-[11px] font-bold", view === item ? "bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]" : "text-[hsl(var(--muted-foreground))]")}>{item}</button>)}</div>} /><div className="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-5 py-3"><div className="flex items-center gap-3"><span className="text-[11px] font-bold">Forecast horizon</span>{[7, 30, 90].map((day) => <button key={day} onClick={() => setHorizon(day)} className={cx("rounded-md px-2.5 py-1 text-[10px] font-bold", horizon === day ? "bg-[hsl(var(--muted))] text-[hsl(var(--foreground))]" : "text-[hsl(var(--muted-foreground))]")}>{day} days</button>)}</div><div className="flex items-center gap-3 text-[10px] text-[hsl(var(--muted-foreground))]"><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[hsl(var(--primary))]" />Forecast</span><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#d8a23d]" />Confidence band</span><button onClick={() => downloadText("sales-forecast.csv", ["Period,Forecast,Lower,Upper", ...forecastData.map((point) => `${point.label},${point.forecast},${point.low},${point.high}`)].join("\n"))} className="ml-2 flex items-center gap-1 rounded border border-[hsl(var(--border))] px-2 py-1 font-bold"><Download size={12} />Export</button></div></div><div className="grid grid-cols-1 gap-5 xl:grid-cols-[1.6fr_.8fr]"><Card><CardHead title={`${view} forecast`} sub={`${state.selectedModel} · next ${horizon} days`} /><div className="h-[330px] p-4"><ResponsiveContainer width="100%" height="100%"><AreaChart data={forecastData}><defs><linearGradient id="band" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={gold} stopOpacity={.2} /><stop offset="100%" stopColor={gold} stopOpacity={.04} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#e8e3d8" strokeDasharray="2 4" /><XAxis dataKey="label" tick={{ fontSize: 10, fill: "#8b948e" }} axisLine={false} tickLine={false} /><YAxis tick={{ fontSize: 10, fill: "#8b948e" }} axisLine={false} tickLine={false} width={32} /><Tooltip content={<ChartTip />} /><Area dataKey="high" name="Upper bound" stroke="transparent" fill="url(#band)" isAnimationActive={false} /><Area dataKey="low" name="Lower bound" stroke="transparent" fill="url(#band)" isAnimationActive={false} /><Line dataKey="forecast" name="Forecast units" stroke={teal} strokeWidth={2.8} dot={{ r: 3, fill: teal, strokeWidth: 0 }} isAnimationActive={false} /></AreaChart></ResponsiveContainer></div></Card><Card><CardHead title="Inventory readout" sub="What this forecast implies" /><div className="space-y-4 p-5"><div className="rounded-lg bg-[#f8e9df] p-4"><div className="flex items-center gap-2 text-[11px] font-bold text-[#a65644]"><PackageCheck size={14} />One action to take</div><p className="mt-2 text-[12px] font-semibold leading-5 text-[#70483f]">Add {formatNumber(forecastData.reduce((sum, point) => sum + point.forecast, 0) * .08)} units of PRD-311 to the next purchase order.</p><p className="mt-1 text-[10px] leading-4 text-[#a65644]">Review the confidence band weekly.</p></div><div className="grid grid-cols-2 gap-3"><div className="rounded-lg bg-[hsl(var(--muted))] p-3"><div className="text-[10px] text-[hsl(var(--muted-foreground))]">Expected demand</div><div className="mono mt-1 text-lg font-bold">{formatNumber(forecastData.reduce((sum, point) => sum + point.forecast, 0))}</div><div className="text-[10px] text-[hsl(var(--muted-foreground))">units</div></div><div className="rounded-lg bg-[hsl(var(--muted))] p-3"><div className="text-[10px] text-[hsl(var(--muted-foreground))]">Band width</div><div className="mono mt-1 text-lg font-bold">±10%</div><div className="text-[10px] text-[hsl(var(--muted-foreground))">at horizon</div></div></div><Link href="/results" className="flex items-center justify-center rounded-lg border border-[hsl(var(--border))] py-2.5 text-[11px] font-bold text-[hsl(var(--primary))]">Open decision brief</Link></div></Card></div><Card className="mt-5"><CardHead title="Forecast detail" sub="The first 8 periods of the selected horizon" /><div className="overflow-x-auto"><table className="w-full min-w-[600px] text-left"><thead className="bg-[hsl(var(--muted))]/60 text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><tr>{["Period", "Point forecast", "Lower bound", "Upper bound", "Signal"].map((heading) => <th className="px-5 py-3" key={heading}>{heading}</th>)}</tr></thead><tbody className="divide-y divide-[hsl(var(--border))]">{forecastData.slice(0, 8).map((point, index) => <tr key={point.label}><td className="mono px-5 py-3 text-[11px] font-bold">{point.label}</td><td className="mono px-5 py-3 text-[11px]">{formatNumber(point.forecast)} units</td><td className="mono px-5 py-3 text-[11px] text-[hsl(var(--muted-foreground))]">{formatNumber(point.low)}</td><td className="mono px-5 py-3 text-[11px] text-[hsl(var(--muted-foreground))]">{formatNumber(point.high)}</td><td className="px-5 py-3"><Pill tone={index > 4 ? "warm" : "positive"}>{index > 4 ? "rising" : "on plan"}</Pill></td></tr>)}</tbody></table></div></Card></>;
}

function ResultsPage() {
  const { state } = useForecast(); const winner = state.modelRows[0];
  return <><PageHeading eyebrow="Workflow · 06" title="A brief you can stand behind." description="Consolidated results for planning, review, and the viva. Every number traces back to the uploaded dataset and a reproducible local run." action={<div className="flex items-center gap-2"><button onClick={() => window.print()} className="flex items-center gap-2 rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2 text-[12px] font-semibold"><Download size={14} />Export PDF</button><button onClick={() => downloadText("sales-results.csv", rowsToCsv(state.rows))} className="flex items-center gap-2 rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-[12px] font-semibold text-[hsl(var(--primary-foreground))]"><FileSpreadsheet size={14} />Export CSV</button></div>} /><div className="grid grid-cols-1 gap-5 xl:grid-cols-[1fr_1fr_.9fr]"><Card><CardHead title="The answer in one line" /><div className="p-5"><div className="mb-4 flex h-11 w-11 items-center justify-center rounded-xl bg-[#e3f1e9] text-[#337d61]"><Sparkles size={20} /></div><p className="text-[18px] font-bold leading-7 tracking-[-.03em]">Demand is moving up, and the safest plan is to stock into the momentum.</p><p className="mt-3 text-[11px] leading-5 text-[hsl(var(--muted-foreground))]">The {winner?.model ?? "selected model"} gives the best holdout performance with a {winner?.rmse.toFixed(2) ?? "—"} RMSE. Use it for planning and review the confidence band weekly.</p></div></Card><Card><CardHead title="Model scorecard" sub="Validation metrics" /><div className="p-5"><div className="mb-4 grid grid-cols-3 gap-2">{[["MAE", winner?.mae], ["RMSE", winner?.rmse], ["R² proxy", (winner?.score ?? 0) / 100]].map(([label, value]) => <div className="rounded-lg bg-[hsl(var(--muted))] p-3" key={String(label)}><div className="text-[10px] text-[hsl(var(--muted-foreground))]">{label}</div><div className="mono mt-1 text-lg font-bold">{label === "R² proxy" ? Number(value).toFixed(3) : Number(value).toFixed(2)}</div></div>)}</div><div className="flex items-center justify-between text-[11px]"><span>{winner?.model ?? "—"}</span><Pill tone="positive">selected</Pill></div></div></Card><Card><CardHead title="Run record" sub="For reproducibility" /><div className="space-y-3 p-5 text-[11px]"><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Dataset</span><b>{state.fileName}</b></div><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Observations</span><b className="mono">{formatNumber(state.rows.length)}</b></div><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Features</span><b className="mono">{requiredColumns.length}</b></div><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Run status</span><b className="text-[#3c8d6e]">Complete</b></div><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Processed</span><b>{state.trainedAt}</b></div></div></Card></div><Card className="mt-5"><CardHead title="Methodology, in plain language" sub="A concise walkthrough for your viva" /><div className="grid grid-cols-1 divide-y divide-[hsl(var(--border))] md:grid-cols-4 md:divide-x md:divide-y-0">{[["01", "Prepare", "Validated the seven required fields, removed duplicates, handled invalid rows, and preserved the date grain."], ["02", "Explore", "Measured trend, 7-day seasonality, product and store mix, plus promotion and holiday lift."], ["03", "Compare", "Trained four deterministic approaches and evaluated all on the same 20% holdout window."], ["04", "Decide", "Selected the lowest-error model, then translated its forecast band into a replenishment action."]].map(([num, title, text]) => <div key={num} className="p-5"><div className="mono mb-4 text-[11px] font-bold text-[hsl(var(--primary))]">{num}</div><div className="mb-2 text-[13px] font-bold">{title}</div><p className="text-[11px] leading-5 text-[hsl(var(--muted-foreground))]">{text}</p></div>)}</div></Card><div className="mt-5 grid grid-cols-1 gap-5 lg:grid-cols-[1.2fr_.8fr]"><Card><CardHead title="Recommended operating plan" /><div className="divide-y divide-[hsl(var(--border))]">{[["Replenish PRD-311", "Use the next forecast window to size the order", "Priority"], ["Keep PRD-207 cover steady", "Review after the next promotion", "Monitor"], ["Re-run forecast", "Every Monday morning or after a new file", "Cadence"]].map(([title, text, tag]) => <div key={title} className="flex items-center justify-between gap-3 px-5 py-4"><div><div className="text-[12px] font-bold">{title}</div><div className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">{text}</div></div><Pill tone={tag === "Priority" ? "warm" : tag === "Monitor" ? "positive" : "neutral"}>{tag}</Pill></div>)}</div></Card><Card className="bg-[hsl(var(--sidebar))] text-[hsl(var(--sidebar-foreground))]"><div className="p-5"><div className="mb-4 flex items-center gap-2 text-[11px] font-bold text-[hsl(var(--sidebar-primary))]"><BookOpen size={14} /> Viva prompt</div><p className="text-[15px] font-bold leading-6">“Why didn’t you simply use the model with the highest accuracy?”</p><p className="mt-3 text-[11px] leading-5 text-slate-400">Because the best model is the one that performs well on unseen data, remains explainable, and supports a useful planning decision.</p></div></Card></div></>;
}

function Router() { return <Shell><Switch><Route path="/" component={Overview} /><Route path="/upload" component={UploadPage} /><Route path="/analysis" component={AnalysisPage} /><Route path="/models" component={ModelsPage} /><Route path="/forecast" component={ForecastPage} /><Route path="/results" component={ResultsPage} /><Route component={NotFound} /></Switch></Shell>; }
export default function ForecastApp() { const [state, setState] = useState(initialState); return <ForecastContext.Provider value={{ state, setState }}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><Router /></WouterRouter></ForecastContext.Provider>; }